<?php
namespace App\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ReferentielController extends Controller {public function index(){abort_unless(auth()->user()->isRole('ADMIN','RQ'),403);$regions=DB::table('regions')->orderBy('nom')->get();$localites=DB::table('localites')->join('regions','regions.id','=','localites.region_id')->select('localites.*','regions.nom as region')->orderBy('regions.nom')->get();$ogds=DB::table('ogds')->orderBy('nom')->get();$processus=DB::table('processus')->orderBy('libelle')->get();$provenances=DB::table('provenances')->orderBy('module')->orderBy('libelle')->get();$qualifications=DB::table('qualifications')->orderBy('module')->orderBy('libelle')->get();return view('admin.referentiels',compact('regions','localites','ogds','processus','provenances','qualifications'));}public function store(Request $r){abort_unless(auth()->user()->isRole('ADMIN','RQ'),403);$d=$r->validate(['type'=>'required|in:region,localite,ogd,processus,provenance,qualification','libelle'=>'required|string|max:180','region_id'=>'nullable|required_if:type,localite|exists:regions,id','module'=>'nullable|in:reclamation,assistance,commun','code'=>'nullable|string|max:40']);$now=now();switch($d['type']){case 'region':DB::table('regions')->insert(['code'=>$d['code']??null,'nom'=>$d['libelle'],'actif'=>1,'created_at'=>$now,'updated_at'=>$now]);break;case 'localite':DB::table('localites')->insert(['region_id'=>$d['region_id'],'nom'=>$d['libelle'],'actif'=>1,'created_at'=>$now,'updated_at'=>$now]);break;case 'ogd':DB::table('ogds')->insert(['code'=>$d['code']??null,'nom'=>$d['libelle'],'actif'=>1,'created_at'=>$now,'updated_at'=>$now]);break;case 'processus':DB::table('processus')->insert(['code'=>$d['code']??strtoupper(\Illuminate\Support\Str::slug($d['libelle'],'_')),'libelle'=>$d['libelle'],'actif'=>1,'created_at'=>$now,'updated_at'=>$now]);break;case 'provenance':DB::table('provenances')->insert(['module'=>$d['module']??'commun','libelle'=>$d['libelle'],'actif'=>1,'created_at'=>$now,'updated_at'=>$now]);break;case 'qualification':abort_unless(in_array($d['module']??null,['reclamation','assistance']),422,'Une qualification doit être liée à un module.');DB::table('qualifications')->insert(['module'=>$d['module'],'code'=>$d['code']??null,'libelle'=>$d['libelle'],'actif'=>1,'created_at'=>$now,'updated_at'=>$now]);break;}return back()->with('success','Référentiel ajouté.');}}
